package com.example.qldetai.feature.evaluation; import java.time.*; import org.springframework.data.jpa.repository.*; public interface DefenseSessionRepository extends JpaRepository<DefenseSession,Long>{@Query("select count(d)>0 from DefenseSession d where d.committee.id=:committeeId and d.status='SCHEDULED' and d.startsAt < :endsAt and d.endsAt > :startsAt") boolean hasCommitteeConflict(Long committeeId,LocalDateTime startsAt,LocalDateTime endsAt);}
